import{c as e,Q as a,j as n,m as r}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Claude Blog 跨主題合成分析","description":"","frontmatter":{"title":"Claude Blog 跨主題合成分析","type":"blog-index"},"headers":[],"relativePath":"research/claude-blog/docs/synthesis.md","filePath":"research/claude-blog/docs/synthesis.md","lastUpdated":1785912489000}'),s={name:"research/claude-blog/docs/synthesis.md"};function o(d,t,l,i,p,h){return a(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="claude-blog-跨主題合成分析" tabindex="-1">Claude Blog 跨主題合成分析 <a class="header-anchor" href="#claude-blog-跨主題合成分析" aria-label="Permalink to &quot;Claude Blog 跨主題合成分析&quot;">​</a></h1><blockquote><p>主體基於 52 篇文章（2025-11-13 ~ 2026-04-22）的深度合成； <strong>2026-08-05 增補主題七～九</strong>，涵蓋 2026-04-23 ~ 2026-07-28 的 100 篇新收錄。<br> 見 <a href="./timeline">docs/timeline.md</a> | <a href="./../REPORT">../REPORT.md</a></p></blockquote><hr><h2 id="核心論點-anthropic-的平台化轉型" tabindex="-1">核心論點：Anthropic 的平台化轉型 <a class="header-anchor" href="#核心論點-anthropic-的平台化轉型" aria-label="Permalink to &quot;核心論點：Anthropic 的平台化轉型&quot;">​</a></h2><p>這批文章呈現出一個一致的戰略訊號：<strong>Anthropic 正從「模型供應商」演變為「AI 開發平台」</strong>。</p><p>三個層次同步推進：</p><ol><li><strong>基礎設施層</strong>：Claude Managed Agents（雲端 Agent 基礎設施）+ Compliance API</li><li><strong>工具層</strong>：Claude Code（開發工具）+ MCP（標準協議）+ Skills（領域知識封裝）</li><li><strong>生態層</strong>：Routines、Advisor Tool、Cowork + Plugin（Enterprise 功能矩陣）</li></ol><p>這個演進在 52 篇文章的時間跨度（Nov 2025 ~ Apr 2026）中清晰可見。</p><hr><h2 id="主題一-skills-生態系是-agent-架構的核心" tabindex="-1">主題一：Skills 生態系是 Agent 架構的核心 <a class="header-anchor" href="#主題一-skills-生態系是-agent-架構的核心" aria-label="Permalink to &quot;主題一：Skills 生態系是 Agent 架構的核心&quot;">​</a></h2><h3 id="信號-nov-2025-jan-2026-—-5-篇連續文章" tabindex="-1">信號（Nov 2025 ~ Jan 2026 — 5 篇連續文章） <a class="header-anchor" href="#信號-nov-2025-jan-2026-—-5-篇連續文章" aria-label="Permalink to &quot;信號（Nov 2025 ~ Jan 2026 — 5 篇連續文章）&quot;">​</a></h3><p>Anthropic 從 Nov 2025 開始以連續 5 篇文章系統性建立 Skill 知識體系，優先於任何其他主題。這個序列本身就是戰略訊號：</p><table tabindex="0"><thead><tr><th>文章</th><th>發布時間</th><th>主題</th></tr></thead><tbody><tr><td>Skills explained</td><td>2025-11-13</td><td>Skill 的定位與比較</td></tr><tr><td>How to create Skills</td><td>2025-11-19</td><td>建立方法論</td></tr><tr><td>Organization Skills</td><td>2025-12-18</td><td>組織層級部署</td></tr><tr><td>Extending capabilities</td><td>2025-12-19</td><td>Skill + MCP 協同</td></tr><tr><td>Building agents with Skills</td><td>2026-01-22</td><td>Agent 架構整合</td></tr></tbody></table><h3 id="關鍵框架-職責分離" tabindex="-1">關鍵框架：職責分離 <a class="header-anchor" href="#關鍵框架-職責分離" aria-label="Permalink to &quot;關鍵框架：職責分離&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MCP Server    → 連接（工具、外部 API、資料庫）</span></span>
<span class="line"><span>Skills        → 邏輯（領域知識、工作流、最佳實踐）</span></span>
<span class="line"><span>Subagents     → 任務委派（隔離 context、並行執行）</span></span>
<span class="line"><span>Projects      → 共享 context（跨對話的持久記憶）</span></span></code></pre></div><p><strong>意涵</strong>：Agent 架構不是「訓練更聰明的模型」，而是「正確分配職責」。Skills 是組織機構知識的新容器。</p><hr><h2 id="主題二-生產-agent-工程進入成熟期" tabindex="-1">主題二：生產 Agent 工程進入成熟期 <a class="header-anchor" href="#主題二-生產-agent-工程進入成熟期" aria-label="Permalink to &quot;主題二：生產 Agent 工程進入成熟期&quot;">​</a></h2><h3 id="信號-apr-10-—-三篇同日發布" tabindex="-1">信號（Apr 10 — 三篇同日發布） <a class="header-anchor" href="#信號-apr-10-—-三篇同日發布" aria-label="Permalink to &quot;信號（Apr 10 — 三篇同日發布）&quot;">​</a></h3><p>Apr 10 當天連續發布三篇技術深度文章（協調模式 / 安全 / 工具設計），暗示這些知識已足夠結構化，可以系統輸出。</p><h3 id="關鍵框架-五種協調模式" tabindex="-1">關鍵框架：五種協調模式 <a class="header-anchor" href="#關鍵框架-五種協調模式" aria-label="Permalink to &quot;關鍵框架：五種協調模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>適用條件</th><th>部署廣泛度</th></tr></thead><tbody><tr><td>Generator-Verifier</td><td>有明確評估標準的品質輸出</td><td>最廣泛</td></tr><tr><td>Orchestrator-Subagent</td><td>可預定、有界的子任務</td><td>廣泛</td></tr><tr><td>Agent Teams</td><td>需持續協作的多步驟工作</td><td>中等</td></tr><tr><td>Message Bus</td><td>事件驅動的非同步管道</td><td>特定場景</td></tr><tr><td>Shared State</td><td>Agent 需要即時共享發現</td><td>進階場景</td></tr></tbody></table><p><strong>MCP 的演進定位：</strong></p><p>從「模型可以呼叫工具」→「生產系統的標準化整合層」。3 億月下載量（Apr 2026）印證市場採用已過臨界點。</p><h3 id="給-sre-infra-工程師的意涵" tabindex="-1">給 SRE/Infra 工程師的意涵 <a class="header-anchor" href="#給-sre-infra-工程師的意涵" aria-label="Permalink to &quot;給 SRE/Infra 工程師的意涵&quot;">​</a></h3><p>多 Agent 系統正在成為新的「微服務」：有相似的協調複雜性、狀態管理需求、可觀測性挑戰。<br> → Cowork 採用 OpenTelemetry（Splunk 整合）是先行指標：「Agent Observability」將成為下一個重要技術領域。</p><hr><h2 id="主題三-成本工程成為一等公民" tabindex="-1">主題三：成本工程成為一等公民 <a class="header-anchor" href="#主題三-成本工程成為一等公民" aria-label="Permalink to &quot;主題三：成本工程成為一等公民&quot;">​</a></h2><p>三個不同來源同時指向成本優化，形成系統性「智能成本分層」架構：</p><table tabindex="0"><thead><tr><th>層次</th><th>技術</th><th>降成本幅度</th></tr></thead><tbody><tr><td>API 層</td><td>Advisor Tool（Haiku + Opus）</td><td>-85% 每任務成本</td></tr><tr><td>API 層</td><td>Advisor Tool（Sonnet + Opus）</td><td>-11.9% 成本，+2.7% 效能</td></tr><tr><td>Context 層</td><td>Prompt Caching（靜態前置）</td><td>-90%</td></tr><tr><td>工具層</td><td>MCP Tool Search 模式</td><td>-85% token 用量</td></tr><tr><td>執行層</td><td>xhigh vs max effort</td><td>顯著降低（模型量化未給出）</td></tr></tbody></table><p><strong>三層防線：</strong></p><ul><li>API 層（Advisor）：模型智能分層，高頻任務用低成本模型</li><li>Context 層（Caching）：靜態 context 前置，避免重複 token</li><li>工具層（Tool Search）：按需展開 schema，不一次性載入所有工具定義</li></ul><p>這套架構在 2026 年初已成為 Anthropic 的主流建議，並有具體數字支撐。</p><hr><h2 id="主題四-claude-code-的「開發者-os」野心" tabindex="-1">主題四：Claude Code 的「開發者 OS」野心 <a class="header-anchor" href="#主題四-claude-code-的「開發者-os」野心" aria-label="Permalink to &quot;主題四：Claude Code 的「開發者 OS」野心&quot;">​</a></h2><h3 id="_15-篇文章的一致主題" tabindex="-1">15 篇文章的一致主題 <a class="header-anchor" href="#_15-篇文章的一致主題" aria-label="Permalink to &quot;15 篇文章的一致主題&quot;">​</a></h3><p>不是單點功能，而是完整開發環境（對比 Cursor/Copilot 的純編輯器定位）：</p><table tabindex="0"><thead><tr><th>元件</th><th>文章</th><th>發布時間</th></tr></thead><tbody><tr><td>介面</td><td>桌面 App 重新設計</td><td>Apr 14</td></tr><tr><td>狀態</td><td>Session Management + 1M Context</td><td>Apr 15</td></tr><tr><td>自動化</td><td>Routines</td><td>Apr 14</td></tr><tr><td>並行</td><td>Subagents</td><td>Apr 7</td></tr><tr><td>能力</td><td>Opus 4.7 整合</td><td>Apr 16</td></tr><tr><td>品質</td><td>Code Review</td><td>Mar 9</td></tr><tr><td>度量</td><td>Contribution Metrics</td><td>Jan 29</td></tr><tr><td>社群</td><td>黑客松得獎者</td><td>Apr 20</td></tr></tbody></table><h3 id="非專業開發者是核心市場" tabindex="-1">非專業開發者是核心市場 <a class="header-anchor" href="#非專業開發者是核心市場" aria-label="Permalink to &quot;非專業開發者是核心市場&quot;">​</a></h3><p>黑客松 5 位得獎者中 4 位非專業開發者（律師、醫師、音樂人）：</p><ul><li>CrossBeam（律師）：縮短住宅許可審批</li><li>PostVisit.ai（醫師）：改善心臟科病患後續照護</li><li>Conductr（音樂人）：虛擬樂隊成員</li></ul><p><strong>結論</strong>：Anthropic 不在爭奪「最好的 AI 輔助編程工具」，而在定義「讓非工程師也能建造複雜系統的工具平台」這個新類別。</p><hr><h2 id="主題五-context-engineering-是真正的護城河" tabindex="-1">主題五：Context Engineering 是真正的護城河 <a class="header-anchor" href="#主題五-context-engineering-是真正的護城河" aria-label="Permalink to &quot;主題五：Context Engineering 是真正的護城河&quot;">​</a></h2><p>Carta Healthcare 案例（Apr 8）揭示核心洞見：</p><blockquote><p>「Context Engineering（在執行時組裝正確資訊並正確排序）才是真正的工程瓶頸，而非 prompt 撰寫。」</p></blockquote><p>這在多篇文章中有結構性呼應：</p><ul><li><strong>Prompt Caching</strong>（Apr 2）：控制哪些靜態內容進入 context</li><li><strong>MCP Tool Search</strong>（Apr 22）：動態選擇展開哪些工具 schema</li><li><strong>Progressive Disclosure</strong>（Apr 10, Seeing like an agent）：按需揭露 context</li><li><strong>Session Management</strong>（Apr 15）：rewind/clear/compact 管理 context rot</li></ul><p><strong>結論</strong>：&quot;Prompt Engineering&quot; 的標籤已過時。下一個 3-5 年的核心競爭力是「如何設計讓模型在執行時得到恰好足夠且正確排序的 context」。</p><hr><h2 id="主題六-企業採用數據已有充分說服力" tabindex="-1">主題六：企業採用數據已有充分說服力 <a class="header-anchor" href="#主題六-企業採用數據已有充分說服力" aria-label="Permalink to &quot;主題六：企業採用數據已有充分說服力&quot;">​</a></h2><p>13 篇 Enterprise AI 文章提供了豐富的量化案例：</p><table tabindex="0"><thead><tr><th>企業</th><th>指標</th><th>改善量</th></tr></thead><tbody><tr><td>Carta Healthcare</td><td>臨床擷取準確率</td><td>98-99%</td></tr><tr><td>Harvey</td><td>BigLaw Bench</td><td>90.2%（首個超過 90% 的 Anthropic 模型）</td></tr><tr><td>Anthropic Marketing</td><td>廣告創作時間</td><td>30 分鐘 → 30 秒</td></tr><tr><td>Anthropic Legal</td><td>合規審閱周轉</td><td>2-3 天 → 24 小時</td></tr><tr><td>Thomson Reuters</td><td>法律研究時間</td><td>小時 → 分鐘</td></tr><tr><td>eSentire</td><td>威脅分析</td><td>5 小時 → 7 分鐘（95% 準確率）</td></tr><tr><td>Anthropic Engineering</td><td>每日合併 PR</td><td>+67%</td></tr><tr><td>Claude Code 用量</td><td>程式碼 AI 輔助比例</td><td>70-90%</td></tr></tbody></table><p>這些數字從 Nov 2025 到 Apr 2026 一直在積累，現在已足夠構成「企業 AI ROI 已被量化驗證」的論點。</p><hr><h2 id="跨主題關聯圖" tabindex="-1">跨主題關聯圖 <a class="header-anchor" href="#跨主題關聯圖" aria-label="Permalink to &quot;跨主題關聯圖&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Platform Strategy（平台化）</span></span>
<span class="line"><span>├── Claude Managed Agents (Apr 8)</span></span>
<span class="line"><span>│   └── 解決基礎設施複雜性 → 開發者專注於邏輯</span></span>
<span class="line"><span>├── Cowork for Enterprise (Apr 9)</span></span>
<span class="line"><span>│   └── RBAC + OTel + 預算控制 → 企業治理</span></span>
<span class="line"><span>├── Compliance API (Mar 30)</span></span>
<span class="line"><span>│   └── 審計日誌 → 合規可觀測性</span></span>
<span class="line"><span>└── MCP (Apr 22)</span></span>
<span class="line"><span>    └── 標準協議層 → 生態整合</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Skills Ecosystem（知識封裝）</span></span>
<span class="line"><span>├── Skills defined (Nov 2025)</span></span>
<span class="line"><span>├── Organization Skills (Dec 2025)</span></span>
<span class="line"><span>├── Cowork Plugins (Jan–Feb 2026)</span></span>
<span class="line"><span>│   └── Finance / Enterprise / 跨部門插件</span></span>
<span class="line"><span>└── MCP + Skills 協同 (Dec 2025, Apr 2026)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Cost Engineering（成本分層）</span></span>
<span class="line"><span>├── Advisor Tool (Apr 9) → 模型分層（API 層）</span></span>
<span class="line"><span>├── Prompt Caching (Apr 2) → Context 靜態化</span></span>
<span class="line"><span>├── Tool Search (Apr 22) → 動態工具展開（工具層）</span></span>
<span class="line"><span>└── xhigh effort → 動態 token 控制</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Developer Experience（開發者體驗）</span></span>
<span class="line"><span>├── Desktop Redesign (Apr 14) → 並行工作介面</span></span>
<span class="line"><span>├── Routines (Apr 14) → 自動化排程</span></span>
<span class="line"><span>├── Session Management (Apr 15) → Context 管理</span></span>
<span class="line"><span>├── Code Review (Mar 9) → 多 Agent 品質保證</span></span>
<span class="line"><span>└── Subagents (Apr 7) → 隔離 + 並行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Technical Depth（技術框架）</span></span>
<span class="line"><span>├── 5-Pattern Coordination (Apr 10) → 架構決策框架</span></span>
<span class="line"><span>├── Tool Design Philosophy (Apr 10) → Agent 工具設計</span></span>
<span class="line"><span>├── Context Engineering (Apr 8) → 新的核心能力定義</span></span>
<span class="line"><span>└── Common Workflow Patterns (Mar 5) → 模式選擇邏輯</span></span></code></pre></div><hr><h2 id="對-zeuik-的實用建議" tabindex="-1">對 Zeuik 的實用建議 <a class="header-anchor" href="#對-zeuik-的實用建議" aria-label="Permalink to &quot;對 Zeuik 的實用建議&quot;">​</a></h2><h3 id="優先嘗試-本週可行" tabindex="-1">優先嘗試（本週可行） <a class="header-anchor" href="#優先嘗試-本週可行" aria-label="Permalink to &quot;優先嘗試（本週可行）&quot;">​</a></h3><ol><li><strong>Advisor Tool 整合</strong>：如果有 Claude API 用量，一行程式碼實作。BrowseComp 翻倍效能，成本降 85%。</li><li><strong>Prompt Caching</strong>：靜態 system prompt 前置，立即降 90% 成本。所有 API 呼叫都應啟用。</li><li><strong>xhigh effort 設定</strong>：比 max 更省 token，同等輸出品質。作為 Claude Code 工作的預設。</li></ol><h3 id="中期架構考量" tabindex="-1">中期架構考量 <a class="header-anchor" href="#中期架構考量" aria-label="Permalink to &quot;中期架構考量&quot;">​</a></h3><ul><li><strong>MCP Tool Search 模式</strong>：替換「一次展開所有工具 schema」的設計，降低 85% token 用量。</li><li><strong>五種協調模式</strong>：下次設計多 Agent 流程時，先對應到這個框架再決定實作。</li><li><strong>Skills 設計</strong>：把機構知識（SRE runbook、FinOps 流程、DB 操作手冊）打包成 Skill，而非每次重新 prompt。</li><li><strong>Context Engineering</strong>：不要把這個標籤給 PM 或非工程師。這是需要系統設計的工程問題。</li></ul><h3 id="長期觀察" tabindex="-1">長期觀察 <a class="header-anchor" href="#長期觀察" aria-label="Permalink to &quot;長期觀察&quot;">​</a></h3><ul><li><strong>Agent Observability</strong>：OpenTelemetry 在 Cowork 的採用是信號。接下來 6 個月應有更多工具出現（Prometheus for Agents？）。</li><li><strong>非工程師建造者</strong>：如果你有做 internal tools，考慮 Claude Code 作為讓非工程同事自助的工具。</li><li><strong>Context Engineering 專門化</strong>：這將成為區分普通 AI 用戶和進階 AI 工程師的核心技能。</li><li><strong>Skills 生態系</strong>：跨企業的 Skill 可攜性（Agent Skills 開放標準）可能在 2026 下半年成為新主題。</li></ul><hr><hr><h1 id="增補-2026-04-23-2026-07-28-的三個轉向" tabindex="-1">增補：2026-04-23 ~ 2026-07-28 的三個轉向 <a class="header-anchor" href="#增補-2026-04-23-2026-07-28-的三個轉向" aria-label="Permalink to &quot;增補：2026-04-23 ~ 2026-07-28 的三個轉向&quot;">​</a></h1><blockquote><p>這 100 篇新收錄裡，有三個方向與前六個主題不是延伸而是<strong>反轉</strong>。分開列出，避免被舊結論覆蓋。</p></blockquote><h2 id="主題七-從「堆規則」轉向「信任判斷」" tabindex="-1">主題七：從「堆規則」轉向「信任判斷」 <a class="header-anchor" href="#主題七-從「堆規則」轉向「信任判斷」" aria-label="Permalink to &quot;主題七：從「堆規則」轉向「信任判斷」&quot;">​</a></h2><h3 id="信號" tabindex="-1">信號 <a class="header-anchor" href="#信號" aria-label="Permalink to &quot;信號&quot;">​</a></h3><p>《<a href="https://claude.com/blog/the-new-rules-of-context-engineering-for-claude-5-generation-models" target="_blank" rel="noreferrer">The new rules of context engineering for Claude 5 generation models</a>》（2026-07-24）給了一個難以忽視的實證錨點：</p><blockquote><p>Anthropic 為 Opus 5 / Fable 5 <strong>刪掉 Claude Code system prompt 的 80% 以上</strong>，在其 coding evals 上<strong>無可量測退化</strong>。</p></blockquote><p>根因不是「模型變強所以規則不重要」，而是<strong>舊 prompt 對模型 over-constrain，且指令彼此打架</strong>——同一次請求裡同時出現「leave documentation as appropriate」與「DO NOT add comments」。新世代模型會花推理預算去調解衝突訊息，所以「多加一條保險條文」不是零成本。</p><h3 id="六條-then-→-now" tabindex="-1">六條 Then → Now <a class="header-anchor" href="#六條-then-→-now" aria-label="Permalink to &quot;六條 Then → Now&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>規則</th><th>內容</th></tr></thead><tbody><tr><td>1</td><td>Judgment over rules</td><td>用「寫得像周遭程式碼」取代硬性條數禁令</td></tr><tr><td>2</td><td>Tool design over examples</td><td>表達力強的參數與清楚 enumeration 勝過使用範例</td></tr><tr><td>3</td><td>Progressive disclosure</td><td>驗證與 review 指導移出 system prompt，改成按需呼叫的 Skill；工具走 deferred loading</td></tr><tr><td>4</td><td>Simplified descriptions</td><td>指令的正確歸宿是 tool description，不要在 system prompt 重覆</td></tr><tr><td>5</td><td>Auto-memory over manual saving</td><td>不必事事用 <code>#</code> 熱鍵手寫進 CLAUDE.md</td></tr><tr><td>6</td><td>Rich references over simple specs</td><td>也吃 HTML artifact / test suite / code sample / rubric</td></tr></tbody></table><h3 id="context-assembly-四層" tabindex="-1">Context Assembly 四層 <a class="header-anchor" href="#context-assembly-四層" aria-label="Permalink to &quot;Context Assembly 四層&quot;">​</a></h3><table tabindex="0"><thead><tr><th>層</th><th>承載</th></tr></thead><tbody><tr><td>System prompt</td><td>產品脈絡與核心目的（平台持有）</td></tr><tr><td>CLAUDE.md</td><td>輕量 repo 描述 + critical gotchas</td></tr><tr><td>Skills</td><td>編碼團隊意見的輕量指南</td></tr><tr><td>References</td><td>code sample / spec / mockup / test suite</td></tr></tbody></table><h3 id="與主題五的關係" tabindex="-1">與主題五的關係 <a class="header-anchor" href="#與主題五的關係" aria-label="Permalink to &quot;與主題五的關係&quot;">​</a></h3><p>主題五說「Context Engineering 是護城河」——這點沒有被推翻，但<strong>做法反過來了</strong>。2026 上半年的 context engineering 是「精心組裝更多正確資訊」；下半年是「刪掉會互相打架的資訊，讓模型按需取用」。工具面的證據：<code>/doctor</code> 從 v2.1.206 起會主動提出 <code>CLAUDE.md</code> 精簡建議，<code>claude-api</code> skill 新增 <code>prompt-audit</code> 子命令專門稽核「為舊世代寫的 prompt」。</p><p><strong>重要邊界</strong>：可刪的是為補償模型弱點而堆的程序性鷹架，<strong>不是驗證閘門與不可逆操作確認</strong>。能力提升不得換取更少驗證。</p><hr><h2 id="主題八-驗證的觸發權從模型收回-harness" tabindex="-1">主題八：驗證的觸發權從模型收回 harness <a class="header-anchor" href="#主題八-驗證的觸發權從模型收回-harness" aria-label="Permalink to &quot;主題八：驗證的觸發權從模型收回 harness&quot;">​</a></h2><h3 id="信號-1" tabindex="-1">信號 <a class="header-anchor" href="#信號-1" aria-label="Permalink to &quot;信號&quot;">​</a></h3><p>兩件事同時發生，方向一致：</p><ol><li><strong>官方推廣把驗證編碼成 Skill</strong>——《<a href="https://claude.com/blog/building-verification-loops-in-claude-code-with-skills" target="_blank" rel="noreferrer">Building verification loops in Claude Code with skills</a>》（2026-07-22）定義驗證迴圈為「agent 檢查自己的產出並在往下走之前修好失敗項的重複循環」，並給出四種部署形態：standalone / embedded / chained / PR-wide。</li><li><strong>同時把自動觸發關掉</strong>——v2.1.215 起 Claude 不再自行跑 <code>/verify</code> 與 <code>/code-review</code>；v2.1.218 起 <code>/deep-research</code> 同樣改為手動。</li></ol><p>看似矛盾，其實是同一件事：<strong>驗證什麼時候跑，是 harness 的決定，不是模型的判斷</strong>。模型自行決定要不要驗證，正好落在它最有偏誤的地方（self-preferential bias）。</p><h3 id="印證-獨立驗證者的量化效果" tabindex="-1">印證：獨立驗證者的量化效果 <a class="header-anchor" href="#印證-獨立驗證者的量化效果" aria-label="Permalink to &quot;印證：獨立驗證者的量化效果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>來源</th><th>做法</th><th>效果</th></tr></thead><tbody><tr><td><a href="https://claude.com/blog/using-llms-to-secure-source-code" target="_blank" rel="noreferrer">Using LLMs to secure source code</a>（05-27）</td><td>驗證 agent 與 discovery agent 分離，prompt 要求<strong>反駁</strong>而非確認</td><td>false positive 減少約 50%；要求 PoC 後趨近於零</td></tr><tr><td><a href="https://claude.com/blog/how-anthropic-secures-its-ai-native-software-development-lifecycle" target="_blank" rel="noreferrer">How Anthropic secures its AI-native SDLC</a>（07-21）</td><td>多個窄焦點 agent 各持獨立 context 與偏誤審同一個 PR</td><td>加上 SAST 與人工抽樣構成分層防線</td></tr><tr><td><a href="https://claude.com/blog/building-effective-human-agent-teams" target="_blank" rel="noreferrer">Building effective human-agent teams</a>（06-24）</td><td>Doer-Verifier harness（一個執行、一個驗證）</td><td>信任建立後，某工程團隊讓 agent 獨立處理 500 個 bug 修復</td></tr><tr><td><a href="https://claude.com/blog/how-datadog-built-a-universal-machine-tool-for-claude-code" target="_blank" rel="noreferrer">How Datadog built a &quot;universal machine tool&quot;</a>（07-21）</td><td>agent 產規格，<strong>確定性 kernel</strong> 用符號推理與 property testing 驗證後才執行</td><td>小規格一秒內完成驗證</td></tr></tbody></table><p>Datadog 的做法值得特別注意：它把「可驗證性」推到極端——agent 不產出應用程式碼，只產出<strong>精確規格</strong>，執行權交給確定性元件。這是「判斷交給模型、決定交給程序」的最完整實作。</p><h3 id="大規模遷移的同一原則" tabindex="-1">大規模遷移的同一原則 <a class="header-anchor" href="#大規模遷移的同一原則" aria-label="Permalink to &quot;大規模遷移的同一原則&quot;">​</a></h3><p>《<a href="https://claude.com/blog/ai-code-migration" target="_blank" rel="noreferrer">How Anthropic runs large-scale code migrations</a>》（07-16）的六步驟框架裡，<strong>壓力測試既有測試套件</strong>排在翻譯之前——因為沒有客觀評判機制就沒有遷移。核心句是「修復流程而非代碼」，實務原則是「用較小模型處理實作、保留大模型做審查與規則制定」。</p><hr><h2 id="主題九-扇出從「越多越好」轉向「有界治理」" tabindex="-1">主題九：扇出從「越多越好」轉向「有界治理」 <a class="header-anchor" href="#主題九-扇出從「越多越好」轉向「有界治理」" aria-label="Permalink to &quot;主題九：扇出從「越多越好」轉向「有界治理」&quot;">​</a></h2><h3 id="信號-2" tabindex="-1">信號 <a class="header-anchor" href="#信號-2" aria-label="Permalink to &quot;信號&quot;">​</a></h3><p>2026 上半年的敘事是「並行 agent 讓總時間約等於執行一個」。下半年（v2.1.202–221）官方把預設值全面收緊：</p><table tabindex="0"><thead><tr><th>治理項</th><th>新預設</th></tr></thead><tbody><tr><td>每 session subagent 上限</td><td>200</td></tr><tr><td>同時執行 subagent</td><td>20</td></tr><tr><td>巢狀 spawn</td><td><strong>預設關閉</strong></td></tr><tr><td><code>--max-budget-usd</code></td><td>達標後拒絕新 spawn <strong>並中止執行中的背景 agent</strong></td></tr><tr><td>WebSearch</td><td>每 session 200 次</td></tr><tr><td>Task 工具 <code>mode</code> 參數</td><td>廢除，subagent 繼承 parent permission mode</td></tr></tbody></table><p>同期，背景 session 的收尾語義被補上：commit + push 保存工作，只在需要時開 draft PR，<strong>遵守 CLAUDE.md 的 git 指示</strong>，結束時一定回報工作落點。</p><h3 id="安全面的同構轉向" tabindex="-1">安全面的同構轉向 <a class="header-anchor" href="#安全面的同構轉向" aria-label="Permalink to &quot;安全面的同構轉向&quot;">​</a></h3><p>《<a href="https://claude.com/blog/ciso-guide-to-agentic-ai" target="_blank" rel="noreferrer">Zero risk isn&#39;t the job: a CISO&#39;s guide to agentic AI</a>》（07-17）把這個轉向講得最清楚：安全領導者的職責不是追求零風險，而是「<strong>讓代理風險可見且有界</strong>」。四個評估問題：</p><ol><li>代理處理哪些不可信內容？</li><li>能採取什麼行動？</li><li>失控時爆炸半徑多大？</li><li>可觀測性程度如何？</li></ol><p>與《<a href="https://www.anthropic.com/engineering/how-we-contain-claude" target="_blank" rel="noreferrer">How we contain Claude across products</a>》（05-25）的「<strong>環境層優先於模型層</strong>」是同一個原則的兩種說法——模型層防禦永遠無法達 100% 有效，所以邊界要落在確定性的環境約束上。該文還記錄了兩個值得記住的實際事故類型：自製隔離元件比 gVisor/seccomp 等成熟技術更易出漏洞；approval fatigue 會導致安全降級。</p><h3 id="對主題二的修訂" tabindex="-1">對主題二的修訂 <a class="header-anchor" href="#對主題二的修訂" aria-label="Permalink to &quot;對主題二的修訂&quot;">​</a></h3><p>主題二說「生產 Agent 工程進入成熟期」。下半年的補充是：<strong>成熟的標誌不是能開更多 agent，而是知道在哪裡停</strong>。五種協調模式的選擇原則沒變（用解決問題所需的最低複雜度），但現在有了執行層的硬上限來執行這個原則。</p><hr><h2 id="增補後的實用建議-2026-08-版" tabindex="-1">增補後的實用建議（2026-08 版） <a class="header-anchor" href="#增補後的實用建議-2026-08-版" aria-label="Permalink to &quot;增補後的實用建議（2026-08 版）&quot;">​</a></h2><h3 id="立即可做" tabindex="-1">立即可做 <a class="header-anchor" href="#立即可做" aria-label="Permalink to &quot;立即可做&quot;">​</a></h3><ol><li><strong>稽核你的 CLAUDE.md 與 Skill 是否還在為舊世代模型寫作</strong>：跑 <code>/doctor</code> 看精簡建議，跑 <code>claude-api</code> skill 的 <code>prompt-audit</code> 找衝突指令。目標是刪，不是加。</li><li><strong>把「你反覆手動做的品質檢查」編碼成驗證 Skill</strong>：專案特定的確定性規則就是素材（例如「拒絕沒有 backfill 的 drop column migration」）。</li><li><strong>確認驗證由 harness 觸發</strong>：<code>/verify</code>、<code>/code-review</code> 已不再自動跑，任何假設「模型會自己驗」的流程都要改成明確呼叫或 hook。</li><li><strong>檢查權限規則語義變更</strong>：v2.1.214 起單段 <code>dir/**</code> 的 <strong>allow</strong> 規則只匹配 <code>&lt;cwd&gt;/dir</code>，任意深度要寫 <code>**/dir/**</code>。</li></ol><h3 id="架構層" tabindex="-1">架構層 <a class="header-anchor" href="#架構層" aria-label="Permalink to &quot;架構層&quot;">​</a></h3><ul><li><strong>模型選擇改用 class × effort 的二維框架</strong>，而非只挑模型。高 class 低 effort 的 per-task 經濟性有時勝過低 class 模型。</li><li><strong>Advisor 策略的官方實測</strong>：Sonnet + Fable 監督 = Fable-only 效能的 90%、成本 63%。</li><li><strong>自建 eval &gt; 公開 benchmark</strong>：benchmark 對強模型已趨飽和；自建 eval 的另一價值是分辨「模型能力不足」與「整合／context 沒接好」——後者遠比前者常見。</li></ul><hr><p><em>見 <a href="./timeline">timeline.md</a> 查看完整時間軸 · <a href="./../REPORT">../REPORT.md</a> 查看文章統計</em><br><em>主體由 <code>/autoresearch:learn</code> 生成 · 2026-04-23；主題七～九增補 · 2026-08-05</em></p>`,112)])])}const u=e(s,[["render",o]]);export{g as __pageData,u as default};
